#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#define MAX_HEADER 128
#define MAX_BODY 4096
#define MAX_PARAMS 32
#define MAX_KEY_LEN 64
#define MAX_VAL_LEN 256
#define MAX_USERS 16
#define TOKEN_LEN 32

typedef struct {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
} Param;

typedef struct {
    char method[8];
    char path[MAX_VAL_LEN];
    char content_type[MAX_VAL_LEN];
    size_t content_length;
    Param params[MAX_PARAMS];
    int param_count;
    char body[MAX_BODY];
} Request;

typedef struct {
    char username[MAX_KEY_LEN];
    char token[TOKEN_LEN + 1];
    int role;  /* 0=guest, 1=user, 2=admin */
    int active;
    uint64_t created_at;
} Session;

static Session sessions[MAX_USERS];
static int session_count = 0;

/* Constant-time comparison to prevent timing attacks */
static int safe_compare(const char *a, const char *b, size_t len) {
    volatile unsigned char result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= (unsigned char)a[i] ^ (unsigned char)b[i];
    }
    return result;
}

/* URL decode a string in-place - validates hex chars */
static void url_decode(char *dst, const char *src, size_t dst_size) {
    size_t di = 0;
    for (size_t si = 0; src[si] && di < dst_size - 1; si++) {
        if (src[si] == '%' && src[si+1] && src[si+2]) {
            /* Validate hex characters before decoding */
            char c1 = src[si+1], c2 = src[si+2];
            if (((c1 >= '0' && c1 <= '9') || (c1 >= 'a' && c1 <= 'f') || (c1 >= 'A' && c1 <= 'F')) &&
                ((c2 >= '0' && c2 <= '9') || (c2 >= 'a' && c2 <= 'f') || (c2 >= 'A' && c2 <= 'F'))) {
                char hex[3] = {c1, c2, 0};
                char decoded = (char)strtol(hex, NULL, 16);
                /* Reject null bytes in decoded output */
                if (decoded == '\0') {
                    si += 2;
                    continue;
                }
                dst[di++] = decoded;
                si += 2;
            } else {
                dst[di++] = src[si];
            }
        } else if (src[si] == '+') {
            dst[di++] = ' ';
        } else {
            dst[di++] = src[si];
        }
    }
    dst[di] = '\0';
}

/* Parse query string or form body into params */
static int parse_params(const char *data, Param *params, int max_params) {
    int count = 0;
    char buf[MAX_BODY];
    strncpy(buf, data, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';

    char *saveptr = NULL;
    char *pair = strtok_r(buf, "&", &saveptr);
    while (pair && count < max_params) {
        char *eq = strchr(pair, '=');
        if (eq) {
            *eq = '\0';
            url_decode(params[count].key, pair, MAX_KEY_LEN);
            url_decode(params[count].value, eq + 1, MAX_VAL_LEN);
            count++;
        }
        pair = strtok_r(NULL, "&", &saveptr);
    }
    return count;
}

/* Find a parameter value by key */
static const char *get_param(const Param *params, int count, const char *key) {
    for (int i = 0; i < count; i++) {
        if (strcmp(params[i].key, key) == 0) {
            return params[i].value;
        }
    }
    return NULL;
}

/* Authenticate user - returns session index or -1 */
static int authenticate(const char *username, const char *password) {
    /* Simplified auth - in production would check bcrypt hash */
    if (!username || !password) return -1;
    if (strlen(username) == 0 || strlen(username) >= MAX_KEY_LEN) return -1;
    if (strlen(password) < 8) return -1;

    /* Validate username contains only safe characters */
    for (size_t i = 0; username[i]; i++) {
        char c = username[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '_' || c == '-')) {
            return -1;
        }
    }

    /* Create session */
    if (session_count >= MAX_USERS) return -1;

    Session *s = &sessions[session_count];
    memset(s, 0, sizeof(Session));
    strncpy(s->username, username, MAX_KEY_LEN - 1);

    /* Generate token from /dev/urandom */
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;
    unsigned char raw_token[TOKEN_LEN / 2];
    ssize_t rd = read(fd, raw_token, sizeof(raw_token));
    close(fd);
    if (rd != (ssize_t)sizeof(raw_token)) return -1;

    for (int i = 0; i < TOKEN_LEN / 2; i++) {
        snprintf(s->token + i * 2, 3, "%02x", raw_token[i]);
    }

    /* Role assignment - never auto-assign admin */
    s->role = 1;
    s->active = 1;
    s->created_at = 1000000;

    return session_count++;
}

/* Validate session token - returns session index or -1 */
static int validate_token(const char *token) {
    if (!token || strlen(token) != TOKEN_LEN) return -1;

    /* Validate token is hex only */
    for (size_t i = 0; i < TOKEN_LEN; i++) {
        char c = token[i];
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return -1;
    }

    for (int i = 0; i < session_count; i++) {
        if (sessions[i].active &&
            safe_compare(sessions[i].token, token, TOKEN_LEN) == 0) {
            return i;
        }
    }
    return -1;
}

/* Check if user has required role level */
static int check_role(int session_idx, int required_role) {
    if (session_idx < 0 || session_idx >= session_count) return 0;
    if (!sessions[session_idx].active) return 0;
    return sessions[session_idx].role >= required_role;
}

/* Parse an HTTP-like request from a file descriptor */
static int parse_request(FILE *fp, Request *req) {
    memset(req, 0, sizeof(Request));

    char line[MAX_BODY];
    /* Read request line */
    if (!fgets(line, sizeof(line), fp)) return -1;

    char *sp1 = strchr(line, ' ');
    if (!sp1) return -1;
    *sp1 = '\0';
    strncpy(req->method, line, sizeof(req->method) - 1);

    char *sp2 = strchr(sp1 + 1, ' ');
    if (sp2) *sp2 = '\0';

    /* Split path and query string */
    char *qmark = strchr(sp1 + 1, '?');
    if (qmark) {
        *qmark = '\0';
        strncpy(req->path, sp1 + 1, sizeof(req->path) - 1);
        req->param_count = parse_params(qmark + 1, req->params, MAX_PARAMS);
    } else {
        strncpy(req->path, sp1 + 1, sizeof(req->path) - 1);
    }

    /* Read headers */
    while (fgets(line, sizeof(line), fp)) {
        if (line[0] == '\r' || line[0] == '\n') break;
        if (strncasecmp(line, "Content-Length:", 15) == 0) {
            long cl = atol(line + 15);
            if (cl < 0 || cl > MAX_BODY - 1) {
                req->content_length = 0;
            } else {
                req->content_length = (size_t)cl;
            }
        } else if (strncasecmp(line, "Content-Type:", 13) == 0) {
            char *val = line + 13;
            while (*val == ' ') val++;
            strncpy(req->content_type, val, sizeof(req->content_type) - 1);
            /* Remove trailing newline */
            char *nl = strchr(req->content_type, '\n');
            if (nl) *nl = '\0';
            nl = strchr(req->content_type, '\r');
            if (nl) *nl = '\0';
        }
    }

    /* Read body if present */
    if (req->content_length > 0) {
        size_t to_read = req->content_length;
        if (to_read >= MAX_BODY) to_read = MAX_BODY - 1;
        size_t got = fread(req->body, 1, to_read, fp);
        req->body[got] = '\0';

        /* Parse body params if form-encoded */
        if (strstr(req->content_type, "x-www-form-urlencoded")) {
            req->param_count = parse_params(req->body, req->params, MAX_PARAMS);
        }
    }

    return 0;
}

/* Write a user profile to a file - with proper path validation */
static int write_profile(int session_idx, const char *bio) {
    if (session_idx < 0 || session_idx >= session_count) return -1;
    if (!bio) return -1;
    if (strlen(bio) > 512) return -1;

    /* Use a safe filename derived from session index, not username */
    char filepath[MAX_VAL_LEN];
    snprintf(filepath, sizeof(filepath), "/var/data/profiles/user_%d.json", session_idx);

    int fd = open(filepath, O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW, 0640);
    if (fd < 0) return -1;

    /* Escape bio content for JSON safety */
    char safe_bio[1024];
    size_t si = 0, di = 0;
    while (bio[si] && di < sizeof(safe_bio) - 2) {
        if (bio[si] == '"' || bio[si] == '\\') {
            safe_bio[di++] = '\\';
        }
        safe_bio[di++] = bio[si++];
    }
    safe_bio[di] = '\0';

    dprintf(fd, "{\"user\": \"%s\", \"bio\": \"%s\", \"role\": %d}\n",
            sessions[session_idx].username, safe_bio, sessions[session_idx].role);
    close(fd);
    return 0;
}

/* Handle admin endpoint - list all sessions */
static void handle_admin_list(int fd) {
    dprintf(fd, "Active Sessions:\n");
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].active) {
            dprintf(fd, "  [%d] %s (role=%d)\n", i,
                    sessions[i].username, sessions[i].role);
        }
    }
}

/* Handle role update - admin only, cannot escalate to admin */
static int handle_role_update(const Param *params, int param_count, int actor_session) {
    const char *target_user = get_param(params, param_count, "target");
    const char *new_role_str = get_param(params, param_count, "role");

    if (!target_user || !new_role_str) return -1;

    int new_role = atoi(new_role_str);
    /* Only allow setting to user(1) or guest(0), not admin(2) */
    if (new_role < 0 || new_role > 1) return -1;

    /* Cannot modify own role */
    if (strcmp(sessions[actor_session].username, target_user) == 0) return -1;

    /* Find target session */
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].username, target_user) == 0 && sessions[i].active) {
            sessions[i].role = new_role;
            return 0;
        }
    }
    return -1;
}

/* Main request router */
static void route_request(Request *req, int out_fd) {
    /* Public endpoints - no auth required */
    if (strcmp(req->path, "/login") == 0 && strcmp(req->method, "POST") == 0) {
        const char *user = get_param(req->params, req->param_count, "username");
        const char *pass = get_param(req->params, req->param_count, "password");
        int idx = authenticate(user, pass);
        if (idx >= 0) {
            dprintf(out_fd, "200 OK\nToken: %s\n", sessions[idx].token);
        } else {
            dprintf(out_fd, "401 Unauthorized\n");
        }
        return;
    }

    /* All other endpoints require authentication */
    const char *token = get_param(req->params, req->param_count, "token");
    int session_idx = validate_token(token);

    if (session_idx < 0) {
        dprintf(out_fd, "401 Unauthorized\n");
        return;
    }

    /* Profile update endpoint */
    if (strcmp(req->path, "/profile") == 0 && strcmp(req->method, "POST") == 0) {
        const char *bio = get_param(req->params, req->param_count, "bio");
        if (write_profile(session_idx, bio) == 0) {
            dprintf(out_fd, "200 OK\nProfile updated\n");
        } else {
            dprintf(out_fd, "500 Error\n");
        }
        return;
    }

    /* Admin endpoints */
    if (strcmp(req->path, "/admin/list") == 0) {
        if (check_role(session_idx, 2)) {
            handle_admin_list(out_fd);
        } else {
            dprintf(out_fd, "403 Forbidden\n");
        }
        return;
    }

    if (strcmp(req->path, "/admin/role") == 0 && strcmp(req->method, "POST") == 0) {
        /* Role updates require admin privileges */
        if (check_role(session_idx, 2)) {
            if (handle_role_update(req->params, req->param_count, session_idx) == 0) {
                dprintf(out_fd, "200 OK\nRole updated\n");
            } else {
                dprintf(out_fd, "400 Bad Request\n");
            }
        } else {
            dprintf(out_fd, "403 Forbidden\n");
        }
        return;
    }

    dprintf(out_fd, "404 Not Found\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <request_file>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    Request req;
    while (parse_request(fp, &req) == 0) {
        route_request(&req, STDOUT_FILENO);
    }

    fclose(fp);
    return 0;
}
